{
  "implementation": "def solve(case):
    try:
        payload = case["payload"]
        nodes = payload["nodes"]
        required_symbols = set(payload["required_symbols"])
    except (KeyError, TypeError) as e:
        raise ValueError("Invalid case structure") from e
    node_map = {}
    children_map = {}
    for node in nodes:
        nid = node["id"]
        node_map[nid] = node
        children_map.setdefault(node["parent"], []).append(nid)
    root_id = None
    for nid, node in node_map.items():
        if node["parent"] is None:
            if root_id is not None:
                raise ValueError("Multiple roots")
            root_id = nid
    if root_id is None:
        raise ValueError("No root node")
    sorted_ids = sorted(node_map.keys(), key=lambda nid: (-node_map[nid]["depth"], nid))
    removed = set()
    removal_order = []
    for nid in sorted_ids:
        node = node_map[nid]
        if not node["removable"]:
            continue
        if node["symbol"] in required_symbols:
            continue
        if nid == root_id:
            continue
        children = children_map.get(nid, [])
        if any(child not in removed for child in children):
            continue
        removed.add(nid)
        removal_order.append(nid)
    retained_ids = sorted([nid for nid in node_map if nid not in removed])
    total_utility = sum(node_map[nid]["utility"] for nid in retained_ids)
    return {"retained_ids": retained_ids, "removal_order": removal_order, "utility_retained": total_utility}"
}
